function CreateParticle(col)
{
	return {pos:[random()*width, random()*height], vel:[random(),random()], col:col};
}

function LerpCol(a,b,t)
{
	return [lerp(a[0],b[0],t), lerp(a[1],b[1],t), lerp(a[2],b[2],t)];
