class Universe
{
	constructor(numberOfParticles, attractionMatrix, rmax, timestep, halfLife)
	{
		//matrix
		this.attractionMatrix = attractionMatrix;

		//r_max
		this.rmax = rmax;
		this.timestep = timestep;
		this.halfLife = halfLife;
		this.wall = true;

		//viewing params
		this.offset = [0,0];
		this.zoom = 1;
		this.selected = 0;
		this.pause = false;

		//generate particles
		this.particles = [];
		for (let i = 0; i < numberOfParticles; i++)
			this.particles.push(CreateParticle(int(random()*attractionMatrix.length)));

		//generate colours
		this.colours = [];
		for (let i = 0; i < attractionMatrix.length; i++)
			this.colours.push(color(random()*255, random()*255, random()*255));
	}

	Attraction(x,A)
	{
		if (x < 0.3) return (x/0.3) - 1;
		if (x > 1) return 0;
		return (A*(0.35 - Math.abs(x-0.65))) / 0.35;
	}

	Translate(x,y)
	{
		return [(x-width/2)/this.zoom-this.offset[0]+width/2, (y-height/2)/this.zoom-this.offset[1]+height/2];
	}

	GUI()
	{
		let l = this.attractionMatrix.length;
		let bx = width*0.1/l;

		textSize(bx*0.2);
		textAlign(CENTER, CENTER);
		stroke(0,0,0,0);

		//draw matrix
		for (let x = 0; x < l; x++)
		{
			for (let y = 0; y < l; y++)
			{
				//draw box
				let col = LerpCol([200,50,50], [50,200,50], (this.attractionMatrix[x][y]+1)/2);
				fill(col[0], col[1], col[2]);
				rect(x*bx,y*bx,bx,bx);

				//draw text
				fill(255);
				text(int(this.attractionMatrix[x][y]*100)/100, (x+0.5)*bx, (y+0.5)*bx);

				//hover
				if (((window.isBeat || false) || (typeof window.is_silent !== 'undefined' ? !window.is_silent : mouseIsPressed)) && (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) > x*bx && (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) > y*bx && (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) < (x+1)*bx && (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) < (y+1)*bx)
				{
					if (mouseButton == CENTER) this.attractionMatrix[x][y]=0;
					if (mouseButton == LEFT) this.attractionMatrix[x][y]+=deltaTime*0.001;
					if (mouseButton == RIGHT) this.attractionMatrix[x][y]-=deltaTime*0.001;
				}
			}
		}

		//draw headers
		for (let i = 0; i < l; i++)
		{
			//header
			fill(this.colours[i]);
			rect((i+0.2)*bx, 0, bx*0.6, bx*0.1);
			rect(0, (i+0.2)*bx, bx*0.1, bx*0.6);

			//selector
			rect(i*bx, l*bx, bx, bx*0.5);
			if (((window.isBeat || false) || (typeof window.is_silent !== 'undefined' ? !window.is_silent : mouseIsPressed)) && (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)))>(i)*bx && (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))>l*bx && (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)))<(i+1)*bx && (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))<(l+0.5)*bx)
				this.selected = i;
		}
		//draw selected
		fill(255);
		circle((this.selected+0.5)*bx, (l+0.25)*bx, bx*0.1);


	//external controls
	if (((window.isBeat || false) || (typeof window.is_silent !== 'undefined' ? !window.is_silent : mouseIsPressed)))
	{
		//pan
		if (mouseButton == RIGHT)
		{
			this.offset[0] += ((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)))-(window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))))/this.zoom;
			this.offset[1] += ((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))-(window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))))/this.zoom;
		}
		//manipulate particles
		if (mouseButton == LEFT)
		{
			//create
			if (keyIsDown(16)) 
			{
				let p = this.Translate((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))));
				this.particles.push({pos:p, vel:[0,0], col:this.selected});
			}
			//destroy
			if (keyIsDown(17)) 
			{
				var p = this.Translate((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))));
				for (let i = 0; i < this.particles.length; i++)
				{
					if (Vector.Magnitude(Vector.Subtract(p, this.particles[i].pos)) < 20)
					{
						this.particles.splice(i,1);
						i--;
					}
				}
			}
		}
	}
	}

	Draw()
	{
		push();
		translate(width/2, height/2);
		scale(this.zoom);
		translate(this.offset[0]-width/2, this.offset[1]-height/2);


		if (this.wall)
		{
			strokeWeight(10);
			stroke(100);
			fill(0,0,0,0);
			rect(0,0,width,height);
		}

		stroke(0,0,0,0);
		for (let i = 0; i < this.particles.length; i++)
		{
			//draw particle
			fill(this.colours[this.particles[i].col]);
			circle(this.particles[i].pos[0], this.particles[i].pos[1], 10);

			if (this.pause) continue;

			//calculate attraction force
			for (let j = 0; j < this.particles.length; j++)
			{
				//continue if same particle
				if (i == j) continue;

				//calculate attractive force
				let attractVec = Vector.Subtract(this.particles[j].pos, this.particles[i].pos);
				let r = Vector.Magnitude(attractVec) / this.rmax;

				//try to unstick particles
				if (r < 0.01)
				{
					this.particles[i].pos = Vector.Add(this.particles[i].pos, [random()*5-2.5, random()*5-2.5]);
					continue;
				}

				let attractionFactor = this.Attraction(r, this.attractionMatrix[this.particles[i].col][this.particles[j].col]);
				let force = Vector.Scale(attractVec, (this.rmax*attractionFactor)/r);

				if (isFinite(force)) continue;

				//apply numerical integration
				this.particles[i].vel = Vector.Add(this.particles[i].vel, Vector.Scale(force, deltaTime*this.timestep));
			}

			//collisions
			if (this.wall)
			{
				if (this.particles[i].pos[0] < 0)
				{
					this.particles[i].pos[0]=1;
					this.particles[i].vel[0]*=-1;
				}
				if (this.particles[i].pos[1] < 0)
				{
					this.particles[i].pos[1]=1;
					this.particles[i].vel[1]*=-1;
				}
				if (this.particles[i].pos[0] > width)
				{
					this.particles[i].pos[0]=width-1;
					this.particles[i].vel[0]*=-1;
				}
				if (this.particles[i].pos[1] > height)
				{
					this.particles[i].pos[1]=height-1;
					this.particles[i].vel[1]*=-1;
				}
			}

			//friction
			this.particles[i].vel = Vector.Scale(this.particles[i].vel, pow(0.5, deltaTime/this.halfLife));

			//apply numerical integration
			this.particles[i].pos = Vector.Add(this.particles[i].pos, Vector.Scale(this.particles[i].vel, deltaTime*this.timestep));
		}

		pop();
	}
}

// === Tab: gui ===
var settings = QuickSettings.create(0, 0, "Settings", null);
settings.addButton("Toggle Walls", ()=>{
	UNIVERSE.wall = !UNIVERSE.wall;
});
