	UNIVERSE.offset[0] = 0;
	UNIVERSE.offset[1] = 0;
	UNIVERSE.zoom = 1;
});
settings.addButton("Pause/Play", ()=>{
	UNIVERSE.pause = !UNIVERSE.pause;
});
settings.addButton("Add Colour", ()=>{
	//add colour
	UNIVERSE.colours.push(color(random()*255, random()*255, random()*255));
	//add to adjacancy matrix
	for (let i = 0; i < UNIVERSE.attractionMatrix.length; i++)
		UNIVERSE.attractionMatrix[i].push(0);
	UNIVERSE.attractionMatrix.push(new Array(UNIVERSE.attractionMatrix[0].length).fill(0));
});
settings.addButton("Reset", ()=>{
	UNIVERSE = new Universe(200, [[1,0],[0.1,0]], 150, 0.0001, 1000);
});
settings.addButton("Clear", ()=>{
	UNIVERSE.particles = [];
});

